arguments.command:
curl -s "https://www.googleapis.com/calendar/v3/calendars/primary/events?timeMin=2018-06-15T00:00:00-07:00&timeMax=2018-06-25T00:00:00-07:00&singleEvents=true&orderBy=startTime&maxResults=200" -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for e in d.get('items',[]):
    end=e['end'].get('dateTime','')
    print(e['id'],'|',e.get('summary'),'| start:',e['start'].get('dateTime'),'| end:',end,'| loc:',e.get('location'),'| desc:',(e.get('description') or '')[:80])
    if end.endswith('T15:30:00-07:00') or end.endswith('T15:30:00-07:00'):
        print('   ^^^ ENDS 3:30 PM')
print('total:', len(d.get('items',[])))
"

